1	// Shared contract for the native Nxeon Calendar + Tasks (/dashboard/calendar).
2	// Backend (lib/calendar/*, lib/actions-calendar.ts) and UI build against these.
3	// Connects to the customer's SOGo CalDAV over the mail server, authenticating with
4	// the SAME per-user mailbox credential the mail client uses (reuse resolveMailbox
5	// from lib/mail/imap.ts). SOGo DAV base: https://10.20.0.10/SOGo/dav (cert is for
6	// mail.nxeon.cloud → set servername + rejectUnauthorized:false when connecting by IP).
7	
8	export const CALDAV_BASE = process.env.CALDAV_BASE_URL || "https://10.20.0.10/SOGo/dav";
9	export const CALDAV_TLS_SERVERNAME = "mail.nxeon.cloud";
10	
11	export type CalendarInfo = {
12	  id: string; // CalDAV collection url
13	  name: string;
14	  color?: string;
15	  readOnly: boolean;
16	};
17	
18	export type CalAttendee = { name?: string; email: string };
19	
