1	"use server";
2	
3	// Server actions for the native Nxeon webmail client (/dashboard/mail).
4	//
5	// Every action authenticates the caller (`requireUser`, via `resolveMailbox`),
6	// resolves ONLY a mailbox the caller owns, decrypts its stored credential, and
7	// talks to the self-hosted mail server over IMAP/SMTP. Mutating actions are
8	// rate-limited. Bodies are sanitised (`safeHtml`) before leaving the server.
9	//
10	// Signatures are fixed by lib/mail/types.ts — the UI builds against the same
11	// contract, so do not change them here.
12	
13	import nodemailer from "nodemailer";
14	import { requireUser } from "@/lib/auth";
15	import { db } from "@/lib/db";
16	import { decryptSecret } from "@/lib/crypto-box";
17	import { checkRateLimit, type RateLimitOptions } from "@/lib/rate-limit";
18	import {
19	  MAIL_SMTP_HOST,
20	  MAIL_SMTP_PORT,
21	  type ListResult,
22	  type MailboxInfo,
23	  type MailFolder,
24	  type MessageFull,
25	  type MessageSummary,
26	  type SendPayload,
27	} from "@/lib/mail/types";
28	import {
29	  MAIL_TLS_SERVERNAME,
30	  findPreviewPart,
31	  folderRole,
32	  isoDate,
33	  parseMessage,
34	  readFlags,
35	  resolveMailbox,
36	  structureHasAttachments,
37	  toMailAddress,
38	  toMailAddresses,
39	  withImap,
40	  withMailbox,
41	} from "@/lib/mail/imap";
42	import { previewText, safeHtml } from "@/lib/mail/render";
43	import type { ImapFlow } from "imapflow";
44	
45	const PAGE_SIZE = 50;
46	
47	/** Reject with a friendly, throttled error when a per-user limit is exceeded. */
48	function enforceRateLimit(key: string, opts: RateLimitOptions) {
49	  const r = checkRateLimit(key, opts);
50	  if (!r.ok) {
51	    throw new Error(`Too many requests — please wait ${r.retryAfterSec}s and try again.`);
52	  }
53	}
54	
55	// ---------------------------------------------------------------------------
56	// Mailboxes
57	// ---------------------------------------------------------------------------
58	
59	/** The signed-in user's mailboxes with used/quota bytes (best effort per box). */
60	export async function getMailboxes(): Promise<MailboxInfo[]> {
61	  const user = await requireUser();
62	  const boxes = await db.mailbox.findMany({
63	    where: { subscription: { userId: user.id } },
64	    include: { subscription: true },
65	    orderBy: { createdAt: "asc" },
66	  });
67	
68	  const out: MailboxInfo[] = [];
69	  for (const box of boxes) {
70	    const quotaBytes = box.quotaMB ? box.quotaMB * 1024 * 1024 : 0;
71	    const password = decryptSecret(box.passwordEnc);
72	    let usedBytes = 0;
73	    let liveQuota = quotaBytes;
74	    if (password) {
75	      try {
76	        const q = await withImap({ address: box.address, password }, async (client) => {
77	          const quota = await client.getQuota().catch(() => false as const);
78	          if (quota && quota.storage) return quota.storage;
79	          // Fall back to STATUS SIZE on INBOX where QUOTA isn't advertised.
80	          const st = await client.status("INBOX", { size: true }).catch(() => null);
81	          return st?.size != null ? { used: st.size, limit: quotaBytes } : null;
82	        });
83	        if (q) {
84	          usedBytes = q.used ?? 0;
85	          if (q.limit && q.limit > 0) liveQuota = q.limit;
86	        }
87	      } catch {
88	        /* connection/auth issue — report zero usage rather than failing the page */
89	      }
90	    }
91	    out.push({ address: box.address, usedBytes, quotaBytes: liveQuota });
92	  }
93	  return out;
