147	/**
148	 * List a page of messages (newest first). `search` runs an IMAP SEARCH across
149	 * subject / from / to / body. Envelopes + a light body snippet only — never the
150	 * full body — so lists stay cheap.
151	 */
152	export async function listMessages(
153	  folder: string,
154	  page: number,
155	  search?: string,
156	  mailboxAddress?: string,
157	): Promise<ListResult> {
158	  const { cred } = await resolveMailbox(mailboxAddress);
159	  const pageNum = Math.max(1, Math.floor(page) || 1);
160	
161	  return withMailbox(
162	    cred,
163	    folder,
164	    async (client) => {
165	      const term = search?.trim();
166	      const query = term
167	        ? { or: [{ subject: term }, { from: term }, { to: term }, { body: term }] }
168	        : { all: true };
169	      const found = await client.search(query, { uid: true });
170	      const uids = (Array.isArray(found) ? found : []).slice().sort((a, b) => b - a); // newest first
171	
172	      const total = uids.length;
173	      const start = (pageNum - 1) * PAGE_SIZE;
174	      const pageUids = uids.slice(start, start + PAGE_SIZE);
175	      if (pageUids.length === 0) {
176	        return { messages: [], total, page: pageNum, pageSize: PAGE_SIZE };
177	      }
178	
179	      // 1) Cheap metadata pass for the page.
180	      const metaByUid = new Map<number, MessageSummary>();
181	      const previewPartByUid = new Map<number, string>();
182	      for await (const msg of client.fetch(
183	        pageUids,
184	        { uid: true, envelope: true, flags: true, internalDate: true, bodyStructure: true },
185	        { uid: true },
186	      )) {
187	        const flags = readFlags(msg.flags);
188	        const env = msg.envelope;
189	        metaByUid.set(msg.uid, {
190	          uid: msg.uid,
191	          folder,
192	          from: toMailAddress(env?.from?.[0]),
193	          to: toMailAddresses(env?.to),
194	          subject: env?.subject || "(no subject)",
195	          preview: "",
196	          date: isoDate(msg),
197	          seen: flags.seen,
198	          flagged: flags.flagged,
199	          answered: flags.answered,
200	          hasAttachments: structureHasAttachments(msg.bodyStructure),
201	        });
202	        previewPartByUid.set(msg.uid, findPreviewPart(msg.bodyStructure).part);
203	      }
204	
205	      // 2) Snippet pass (partial, PEEKed downloads — no flag changes).
206	      await Promise.all(
207	        pageUids.map(async (uid) => {
208	          const summary = metaByUid.get(uid);
209	          if (!summary) return;
210	          summary.preview = await fetchPreview(client, uid, previewPartByUid.get(uid) || "1");
211	        }),
212	      );
213	
214	      const messages = pageUids
215	        .map((uid) => metaByUid.get(uid))
216	        .filter((m): m is MessageSummary => Boolean(m));
217	      return { messages, total, page: pageNum, pageSize: PAGE_SIZE };
218	    },
219	    { readOnly: true },
220	  );
221	}
