227	/** Fetch one full message: parsed + SANITISED html, attachments listed, marked \Seen. */
228	export async function getMessage(folder: string, uid: number, mailboxAddress?: string): Promise<MessageFull> {
229	  const { cred } = await resolveMailbox(mailboxAddress);
230	
231	  return withMailbox(cred, folder, async (client) => {
232	    const msg = await client.fetchOne(
233	      String(uid),
234	      { uid: true, source: true, flags: true, envelope: true, internalDate: true },
235	      { uid: true },
236	    );
237	    if (!msg || !msg.source) throw new Error("Message not found.");
238	
239	    const parsed = await parseMessage(msg.source);
240	    const flags = readFlags(msg.flags);
241	    const env = msg.envelope;
242	
243	    const attachments = (parsed.attachments || [])
244	      .filter((a) => a.related !== true) // skip inline/embedded (cid) images
245	      .map((a, i) => ({
246	        id: `${uid}:${a.partId ?? String(i + 1)}`,
247	        filename: a.filename || `attachment-${i + 1}`,
248	        mime: a.contentType || "application/octet-stream",
249	        sizeBytes: a.size ?? 0,
250	      }));
251	
252	    const full: MessageFull = {
253	      uid,
254	      folder,
255	      from: toMailAddress(env?.from?.[0]),
256	      to: toMailAddresses(env?.to),
257	      cc: toMailAddresses(env?.cc),
258	      subject: env?.subject || parsed.subject || "(no subject)",
259	      preview: previewText(parsed.text || (typeof parsed.html === "string" ? parsed.html : "")),
260	      date: isoDate(msg),
261	      seen: true, // becomes read as a side effect of opening
262	      flagged: flags.flagged,
263	      answered: flags.answered,
264	      hasAttachments: attachments.length > 0,
265	      html: typeof parsed.html === "string" ? safeHtml(parsed.html) : null,
266	      text: parsed.text ?? null,
267	      attachments,
268	    };
269	
270	    // Mark read (mailbox opened read-write). Best effort — never fail the read.
271	    try {
272	      await client.messageFlagsAdd(String(uid), ["\\Seen"], { uid: true });
273	    } catch {
274	      /* ignore */
275	    }
276	
277	    return full;
278	  });
279	}
