282	// Sending
283	// ---------------------------------------------------------------------------
284	
285	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
286	
287	/** Parse a comma/semicolon-separated recipient string into validated addresses. */
288	function parseRecipients(input: string | undefined): { list: string[]; invalid: string[] } {
289	  const parts = (input || "")
290	    .split(/[,;]+/)
291	    .map((s) => s.trim())
292	    .filter(Boolean);
293	  const list: string[] = [];
294	  const invalid: string[] = [];
295	  for (const p of parts) {
296	    // Tolerate "Name <addr>" form by extracting the address.
297	    const m = p.match(/<([^>]+)>/);
298	    const addr = (m ? m[1] : p).trim();
299	    if (EMAIL_RE.test(addr)) list.push(addr);
300	    else invalid.push(p);
301	  }
302	  return { list, invalid };
303	}
