305	/** Resolve the IMAP path of the mailbox's Sent folder (defaults to "Sent"). */
306	async function findSentPath(client: ImapFlow): Promise<string> {
307	  try {
308	    const list = await client.list();
309	    const sent = list.find((f) => folderRole(f.path, f.specialUse) === "sent");
310	    return sent?.path || "Sent";
311	  } catch {
312	    return "Sent";
313	  }
314	}
