424	/** Move a message from one folder to another. */
425	export async function moveMessage(
426	  folder: string,
427	  uid: number,
428	  toFolder: string,
429	  mailboxAddress?: string,
430	): Promise<void> {
431	  const { user, cred } = await resolveMailbox(mailboxAddress);
432	  enforceRateLimit(`mail:move:${user.id}`, { max: 120, windowMs: 60 * 1000 });
433	  await withMailbox(cred, folder, async (client) => {
434	    await client.messageMove(String(uid), toFolder, { uid: true });
435	  });
436	}
