// DAVClient factory and the thin fetch/put/delete helpers shared by the server
// actions (lib/actions-calendar.ts). It talks to the customer's SOGo CalDAV
// collections over the mail server, authenticating with the SAME per-user
// mailbox credential the webmail client uses (see resolveMailbox). It is never
// imported into a client bundle.

import { DAVClient } from "tsdav";
import type { DAVCalendar, DAVCalendarObject } from "tsdav";
import { Agent } from "undici";
import { CALDAV_BASE, CALDAV_TLS_SERVERNAME } from "./types";
import type { MailboxCredentials } from "@/lib/mail/imap";

// ---------------------------------------------------------------------------
// TLS to an internal IP
// ---------------------------------------------------------------------------
//
// SOGo's certificate is issued for `mail.nxeon.cloud`, but we reach the server
// by its internal address (https://10.20.0.10/SOGo/dav). Verifying the cert
// against the IP would always fail the hostname check, so — exactly like the
// IMAP/SMTP engine (lib/mail/imap.ts) — we disable verification for this
// internal hop while still sending the correct SNI `servername` so the reverse
// proxy in front of SOGo selects the right vhost/certificate.
//
// tsdav uses the global (undici) fetch and forwards `fetchOptions` to it; undici
// honours a `dispatcher` on the request init. A single module-scoped Agent gives
// us connection pooling across requests. RequestInit has no `dispatcher` field in
// its public type, hence the cast.
const caldavDispatcher = new Agent({
  connect: { rejectUnauthorized: false, servername: CALDAV_TLS_SERVERNAME },
});

const caldavFetchOptions = { dispatcher: caldavDispatcher } as unknown as RequestInit;

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

/** Normalise any CalDAV/transport failure into a short, user-safe message. */
export function caldavError(e: unknown): Error {
  const msg = String((e as Error)?.message ?? e ?? "Unknown error");
  // Never leak credentials or raw stack detail to the client.
  return new Error(`Calendar server error: ${msg.slice(0, 200)}`);
}

// ---------------------------------------------------------------------------
// Client factory
// ---------------------------------------------------------------------------

/**
 * Build a logged-in tsdav DAVClient for the given mailbox credential. Login runs
 * CalDAV service discovery (principal + calendar-home) so `fetchCalendars` works.
 * Throws a clean `caldavError` on any connection/auth failure.
 */
export async function caldavClient(cred: MailboxCredentials): Promise<DAVClient> {
  try {
    const client = new DAVClient({
      serverUrl: CALDAV_BASE,
      credentials: { username: cred.address, password: cred.password },
      authMethod: "Basic",
      defaultAccountType: "caldav",
      fetchOptions: caldavFetchOptions,
    });
    await client.login();
    return client;
  } catch (e) {
    throw caldavError(e);
  }
}

// ---------------------------------------------------------------------------
// Reads
// ---------------------------------------------------------------------------

/** All calendar collections in the account (events + tasks live here). */
export async function fetchCalendars(client: DAVClient): Promise<DAVCalendar[]> {
  try {
    return await client.fetchCalendars();
  } catch (e) {
    throw caldavError(e);
  }
}

/**
 * Fetch the VEVENT objects of a calendar that overlap [startISO, endISO).
 * Uses the default VEVENT comp-filter with a server-side time-range so we never
 * download the whole collection.
 */
export async function fetchEventObjects(
  client: DAVClient,
  calendar: DAVCalendar,
  startISO: string,
  endISO: string,
): Promise<DAVCalendarObject[]> {
  try {
    return await client.fetchCalendarObjects({
      calendar,
      timeRange: { start: startISO, end: endISO },
    });
  } catch (e) {
    throw caldavError(e);
  }
}

/**
 * Fetch the VTODO objects of a calendar. Time-range filtering on VTODO is poorly
 * supported across servers, so we request an explicit VTODO comp-filter and let
 * the caller parse them (tasks are few relative to events).
 */
export async function fetchTaskObjects(
  client: DAVClient,
  calendar: DAVCalendar,
): Promise<DAVCalendarObject[]> {
  try {
    return await client.fetchCalendarObjects({
      calendar,
      filters: [
        {
          "comp-filter": {
            _attributes: { name: "VCALENDAR" },
            "comp-filter": { _attributes: { name: "VTODO" } },
          },
        },
      ],
    });
  } catch (e) {
    throw caldavError(e);
  }
}

/** Fetch a single calendar object by its href (returns null if absent). */
export async function fetchObjectByUrl(
  client: DAVClient,
  calendar: DAVCalendar,
  url: string,
): Promise<DAVCalendarObject | null> {
  try {
    const objs = await client.fetchCalendarObjects({ calendar, objectUrls: [url] });
    return objs[0] ?? null;
  } catch (e) {
    throw caldavError(e);
  }
}

