export async function putObject(
  client: DAVClient,
  calendarUrl: string,
  filename: string,
  iCalString: string,
): Promise<string> {
  try {
    const res = await client.createCalendarObject({
      calendar: { url: calendarUrl } as DAVCalendar,
      iCalString,
      filename,
    });
    if (!res.ok) {
      throw new Error(`${res.status} ${res.statusText}`);
    }
    return objectUrlFor(calendarUrl, filename);
  } catch (e) {
    throw caldavError(e);
  }
