export async function putObjectAt(client: DAVClient, url: string, iCalString: string): Promise<void> {
  try {
    const res = await client.updateCalendarObject({
      calendarObject: { url, data: iCalString },
    });
    if (!res.ok) {
      throw new Error(`${res.status} ${res.statusText}`);
    }
  } catch (e) {
    throw caldavError(e);
  }
}

/** Delete an object by its href. */
export async function deleteObjectAt(client: DAVClient, url: string): Promise<void> {
  try {
    const res = await client.deleteCalendarObject({ calendarObject: { url } });
    if (!res.ok && res.status !== 404) {
      throw new Error(`${res.status} ${res.statusText}`);
    }
  } catch (e) {
    throw caldavError(e);
  }
}
