// iCalendar (RFC 5545) parsing + building for the native Nxeon Calendar + Tasks
// feature, backed by ical.js.
//
// Plain server-side module (NOT "use server"). It converts the raw .ics bodies
// returned by CalDAV into our CalEvent / TaskItem contract shapes, and builds
// fresh .ics bodies from EventInput / TaskInput for create/update. All emitted
// date-times are in UTC.

import ICAL from "ical.js";
import type { CalAttendee, CalEvent, EventInput, TaskInput, TaskItem } from "./types";

// ical.js's default export is a namespace object of classes. Alias the instance
// types via the constructors so we can annotate without pulling type-space paths.
type ICALComponent = InstanceType<typeof ICAL.Component>;
type ICALTime = InstanceType<typeof ICAL.Time>;
type ICALProperty = InstanceType<typeof ICAL.Property>;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** A fresh globally-unique iCal UID. */
export function newUID(): string {
  return crypto.randomUUID();
}

/** The current instant as a UTC ICAL.Time (for DTSTAMP / COMPLETED). */
function nowUTC(): ICALTime {
  return ICAL.Time.fromJSDate(new Date(), true);
}

/** Convert an ISO string to a UTC ICAL.Time; set VALUE=DATE for all-day. */
function toICALTime(iso: string, allDay: boolean): ICALTime {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) throw new Error(`Invalid date: ${iso}`);
  const t = ICAL.Time.fromJSDate(d, true);
  if (allDay) t.isDate = true;
  return t;
}

/** Read a component property value as a trimmed string ("" when missing). */
function getStr(comp: ICALComponent, name: string): string {
  const v = comp.getFirstPropertyValue(name);
  if (v == null) return "";
  return typeof v === "string" ? v : String(v);
}

/** ISO string from any ical.js value that carries a toJSDate() (Time), else undefined. */
function timeToISO(v: unknown): string | undefined {
  const t = v as { toJSDate?: () => Date } | null;
  if (t && typeof t.toJSDate === "function") {
    const d = t.toJSDate();
    if (d instanceof Date && !Number.isNaN(d.getTime())) return d.toISOString();
  }
  return undefined;
}

/** Clamp an iCal PRIORITY to its valid 0-9 range. */
function clampPriority(p: number): number {
  return Math.min(9, Math.max(0, Math.round(p)));
}

/** Parse ATTENDEE properties into our CalAttendee shape (undefined when none). */
function parseAttendees(props: ICALProperty[]): CalAttendee[] | undefined {
  const list: CalAttendee[] = [];
  for (const p of props) {
    const raw = String(p.getFirstValue() ?? "");
    const email = raw.replace(/^mailto:/i, "").trim();
    if (!email) continue;
    const cn = p.getParameter("cn");
    const name = Array.isArray(cn) ? String(cn[0] ?? "") : cn ? String(cn) : "";
    list.push({ email, name: name || undefined });
  }
  return list.length ? list : undefined;
}

/** Parse an iCalendar string into a root VCALENDAR component, or null if invalid. */
function parseRoot(icsData: string): ICALComponent | null {
  try {
    return new ICAL.Component(ICAL.parse(icsData));
  } catch {
    return null;
  }
}

// ---------------------------------------------------------------------------
// Parse: iCalendar -> contract types
// ---------------------------------------------------------------------------

/**
 * Parse the VEVENT(s) in one calendar object into CalEvent[]. `href` is the
 * object's CalDAV url and becomes the event id (used for update/delete);
 * `calendarId` is the owning collection url.
 */
export function parseCalEvents(icsData: string, calendarId: string, href: string): CalEvent[] {
  const root = parseRoot(icsData);
  if (!root) return [];
  const out: CalEvent[] = [];
  for (const ve of root.getAllSubcomponents("vevent")) {
    try {
      const event = new ICAL.Event(ve);
      const startT = event.startDate;
      if (!startT) continue;
      const allDay = startT.isDate === true;
      let endT: ICALTime | null = null;
      try {
        endT = event.endDate;
      } catch {
        endT = null;
      }
      out.push({
        id: href,
        uid: event.uid || getStr(ve, "uid") || href,
        calendarId,
        title: event.summary || "(untitled)",
        description: event.description || undefined,
        location: event.location || undefined,
        start: startT.toJSDate().toISOString(),
        end: (endT ?? startT).toJSDate().toISOString(),
        allDay,
        attendees: parseAttendees(event.attendees),
      });
    } catch {
      /* skip a malformed component rather than failing the whole fetch */
    }
  }
  return out;
}

/**
 * Parse the VTODO(s) in one calendar object into TaskItem[]. `href` becomes the
 * task id; `calendarId` is the owning collection url.
 */
export function parseTaskItems(icsData: string, calendarId: string, href: string): TaskItem[] {
  const root = parseRoot(icsData);
  if (!root) return [];
  const out: TaskItem[] = [];
  for (const vt of root.getAllSubcomponents("vtodo")) {
    try {
      const status = getStr(vt, "status").toUpperCase();
      const completed = status === "COMPLETED" || vt.hasProperty("completed");
      const due = timeToISO(vt.getFirstPropertyValue("due"));
      const prio = vt.getFirstPropertyValue("priority");
      const priority = typeof prio === "number" ? prio : undefined;
      out.push({
        id: href,
        uid: getStr(vt, "uid") || href,
        calendarId,
        title: getStr(vt, "summary") || "(untitled)",
        notes: getStr(vt, "description") || undefined,
        due,
        completed,
        priority,
      });
    } catch {
      /* skip malformed component */
    }
  }
  return out;
}

// ---------------------------------------------------------------------------
// Build: contract types -> iCalendar
// ---------------------------------------------------------------------------

/** A new VCALENDAR wrapper carrying our PRODID / VERSION. */
function newCalendar(): ICALComponent {
  const cal = new ICAL.Component(["vcalendar", [], []]);
  cal.updatePropertyWithValue("version", "2.0");
  cal.updatePropertyWithValue("prodid", "-//Nxeon//Calendar//EN");
  return cal;
}

/**
 * Build a complete VCALENDAR/VEVENT iCalendar string from an EventInput.
 * Pass the `uid` (fresh via newUID() for create, the existing UID for update).
 */
export function buildEventICS(input: EventInput, uid: string): string {
  const cal = newCalendar();
  const ve = new ICAL.Component("vevent");
  const allDay = input.allDay === true;

  ve.updatePropertyWithValue("uid", uid);
  ve.updatePropertyWithValue("dtstamp", nowUTC());
  ve.updatePropertyWithValue("dtstart", toICALTime(input.start, allDay));
  ve.updatePropertyWithValue("dtend", toICALTime(input.end, allDay));
  ve.updatePropertyWithValue("summary", input.title);
  if (input.description) ve.updatePropertyWithValue("description", input.description);
  if (input.location) ve.updatePropertyWithValue("location", input.location);
  for (const a of input.attendees ?? []) {
    const email = a?.email?.trim();
    if (!email) continue;
    const prop = ve.addPropertyWithValue("attendee", `mailto:${email}`);
    if (a.name) prop.setParameter("cn", a.name);
  }

  cal.addSubcomponent(ve);
  return cal.toString();
}

/**
 * Build a complete VCALENDAR/VTODO iCalendar string from a TaskInput.
 * `completed` seeds the initial status (a new task defaults to open).
 */
export function buildTaskICS(input: TaskInput, uid: string, completed = false): string {
  const cal = newCalendar();
  const vt = new ICAL.Component("vtodo");

  vt.updatePropertyWithValue("uid", uid);
  vt.updatePropertyWithValue("dtstamp", nowUTC());
  vt.updatePropertyWithValue("summary", input.title);
  if (input.notes) vt.updatePropertyWithValue("description", input.notes);
  if (input.due) vt.updatePropertyWithValue("due", toICALTime(input.due, false));
  if (typeof input.priority === "number") {
    vt.updatePropertyWithValue("priority", clampPriority(input.priority));
  }
  applyTodoCompletion(vt, completed);

  cal.addSubcomponent(vt);
  return cal.toString();
}

/** Set/clear COMPLETED state on a VTODO component (status, percent, timestamp). */
function applyTodoCompletion(vt: ICALComponent, completed: boolean): void {
  vt.removeAllProperties("status");
  vt.removeAllProperties("percent-complete");
  vt.removeAllProperties("completed");
  if (completed) {
    vt.updatePropertyWithValue("status", "COMPLETED");
    vt.updatePropertyWithValue("percent-complete", 100);
    vt.updatePropertyWithValue("completed", nowUTC());
  } else {
    vt.updatePropertyWithValue("status", "NEEDS-ACTION");
  }
}

/**
 * Toggle completion on an existing VTODO's iCalendar body while preserving all
 * its other fields (summary, due, priority, notes). Bumps DTSTAMP. Returns the
 * updated string, or null if the body has no parseable VTODO.
 */
export function setTaskCompletedInICS(icsData: string, completed: boolean): string | null {
  const root = parseRoot(icsData);
  if (!root) return null;
  const vt = root.getFirstSubcomponent("vtodo");
  if (!vt) return null;
  applyTodoCompletion(vt, completed);
  vt.removeAllProperties("dtstamp");
  vt.updatePropertyWithValue("dtstamp", nowUTC());
  return root.toString();
}

/** Extract the first UID found in a calendar object body, if any. */
export function uidFromICS(icsData: string): string | null {
  const root = parseRoot(icsData);
  if (!root) return null;
  const comp = root.getFirstSubcomponent("vevent") ?? root.getFirstSubcomponent("vtodo");
  if (!comp) return null;
  const uid = getStr(comp, "uid");
  return uid || null;
}
