"use server";

// Server actions for the native Nxeon Calendar + Tasks feature
// (/dashboard/calendar).
//
// Every action authenticates the caller (`requireUser`, via `resolveMailbox`),
// resolves ONLY a mailbox the caller owns, decrypts its stored credential, and
// talks to the customer's SOGo CalDAV over the mail server — reusing the SAME
// per-user mailbox credential the webmail client uses. Mutating actions are
// rate-limited and validate their input. The password never leaves the server.
//
// Signatures are fixed by lib/calendar/types.ts — the UI builds against the same
// contract, so do not change them here.

import { resolveMailbox } from "@/lib/mail/imap";
import { checkRateLimit, type RateLimitOptions } from "@/lib/rate-limit";
import type {
  CalEvent,
  CalendarInfo,
  EventInput,
  TaskInput,
  TaskItem,
} from "@/lib/calendar/types";
import {
  caldavClient,
  deleteObjectAt,
  fetchCalendars,
  fetchEventObjects,
  fetchObjectByUrl,
  fetchTaskObjects,
  putObject,
  putObjectAt,
} from "@/lib/calendar/caldav";
import {
  buildEventICS,
  buildTaskICS,
  newUID,
  parseCalEvents,
  parseTaskItems,
  setTaskCompletedInICS,
  uidFromICS,
} from "@/lib/calendar/ical";
import type { DAVCalendar, DAVClient } from "tsdav";

// ---------------------------------------------------------------------------
// Internal helpers (not exported — this is a "use server" module)
// ---------------------------------------------------------------------------

/** Reject with a friendly, throttled error when a per-user limit is exceeded. */
function enforceRateLimit(key: string, opts: RateLimitOptions) {
  const r = checkRateLimit(key, opts);
  if (!r.ok) {
    throw new Error(`Too many requests — please wait ${r.retryAfterSec}s and try again.`);
  }
}

/** Apply the standard mutation rate limits (short burst + hourly ceiling). */
function limitMutations(userId: string) {
  enforceRateLimit(`cal:mutate:burst:${userId}`, { max: 30, windowMs: 60 * 1000 });
  enforceRateLimit(`cal:mutate:${userId}`, { max: 600, windowMs: 60 * 60 * 1000 });
}

/** True for a parseable ISO date-time string. */
function isValidISO(s: unknown): s is string {
  return typeof s === "string" && s.trim() !== "" && !Number.isNaN(Date.parse(s));
}

/** Short, client-safe message from a thrown value. */
function cleanMsg(e: unknown): string {
  return String((e as Error)?.message ?? e ?? "Unknown error").slice(0, 300);
}

/** Normalise a collection/object url for comparison (drop trailing slashes). */
function normUrl(u: string): string {
  return u.replace(/\/+$/, "");
}

/** Does a calendar advertise support for the given component (VEVENT/VTODO)? */
function supportsComponent(cal: DAVCalendar, comp: string): boolean {
  const comps = cal.components;
  if (!comps || comps.length === 0) return true; // unknown — include it
  return comps.some((c) => c.toUpperCase() === comp);
}

/** Human-friendly calendar name, falling back to the last url segment. */
function calName(cal: DAVCalendar): string {
  const dn = cal.displayName;
  if (typeof dn === "string" && dn.trim()) return dn.trim();
  const leaf = decodeURIComponent(normUrl(cal.url).split("/").pop() || "");
  return leaf || "Calendar";
}

/** Map a tsdav DAVCalendar to the contract CalendarInfo. */
function toCalendarInfo(cal: DAVCalendar): CalendarInfo {
  return {
    id: cal.url,
    name: calName(cal),
    color: typeof cal.calendarColor === "string" ? cal.calendarColor : undefined,
    // SOGo does not surface a reliable per-collection read-only flag over the
    // default PROPFIND set; treat collections as writable and let the server
    // reject any unauthorised write.
    readOnly: false,
  };
}

/** Verify a calendar id belongs to the authenticated account (defense in depth). */
async function assertOwnedCalendar(client: DAVClient, calendarId: string): Promise<DAVCalendar> {
  const cals = await fetchCalendars(client);
  const target = normUrl(calendarId);
  const match = cals.find((c) => normUrl(c.url) === target);
  if (!match) throw new Error("That calendar was not found in your account.");
  return match;
}

/** The calendar collection url that contains an object href. */
function calendarUrlOf(objectHref: string): string {
  const i = objectHref.lastIndexOf("/");
  return i >= 0 ? objectHref.slice(0, i + 1) : objectHref;
}

/** Read an existing object's body by its href (or null if it is gone). */
async function readObject(client: DAVClient, objectHref: string): Promise<string | null> {
  const calUrl = calendarUrlOf(objectHref);
  const obj = await fetchObjectByUrl(client, { url: calUrl } as DAVCalendar, objectHref);
  return obj?.data ?? null;
}

/** Validate an EventInput; returns an error message or null when valid. */
function validateEventInput(input: EventInput): string | null {
  if (!input || typeof input !== "object") return "Invalid event.";
  if (!input.calendarId?.trim()) return "Choose a calendar.";
  if (!input.title?.trim()) return "Add a title.";
  if (!isValidISO(input.start)) return "Invalid start time.";
  if (!isValidISO(input.end)) return "Invalid end time.";
  if (Date.parse(input.end) < Date.parse(input.start)) return "End must be after start.";
  return null;
}

/** Validate a TaskInput; returns an error message or null when valid. */
function validateTaskInput(input: TaskInput): string | null {
  if (!input || typeof input !== "object") return "Invalid task.";
  if (!input.calendarId?.trim()) return "Choose a calendar.";
  if (!input.title?.trim()) return "Add a title.";
  if (input.due != null && !isValidISO(input.due)) return "Invalid due date.";
  if (
    input.priority != null &&
    (typeof input.priority !== "number" || input.priority < 0 || input.priority > 9)
  ) {
    return "Priority must be between 0 and 9.";
  }
  return null;
}

// ---------------------------------------------------------------------------
// Calendars
// ---------------------------------------------------------------------------

/** List the CalDAV calendar collections in the user's account. */
export async function listCalendars(mailboxAddress?: string): Promise<CalendarInfo[]> {
  const { cred } = await resolveMailbox(mailboxAddress);
  const client = await caldavClient(cred);
  const cals = await fetchCalendars(client);
  return cals.map(toCalendarInfo);
}

// ---------------------------------------------------------------------------
// Events
// ---------------------------------------------------------------------------

/** All events across the user's calendars overlapping [rangeStart, rangeEnd). */
export async function listEvents(
  rangeStartISO: string,
  rangeEndISO: string,
  mailboxAddress?: string,
): Promise<CalEvent[]> {
  if (!isValidISO(rangeStartISO) || !isValidISO(rangeEndISO)) {
    throw new Error("Invalid date range.");
  }
  const { cred } = await resolveMailbox(mailboxAddress);
  const client = await caldavClient(cred);
  const cals = (await fetchCalendars(client)).filter((c) => supportsComponent(c, "VEVENT"));

  const perCal = await Promise.all(
    cals.map(async (cal) => {
      const objs = await fetchEventObjects(client, cal, rangeStartISO, rangeEndISO);
      return objs.flatMap((o) => (o.data ? parseCalEvents(o.data, cal.url, o.url) : []));
    }),
  );
  return perCal.flat();
}

/** Create a new event: PUT a fresh .ics object into the target calendar. */
export async function createEvent(
  input: EventInput,
  mailboxAddress?: string,
): Promise<{ ok: boolean; id?: string; error?: string }> {
  const { user, cred } = await resolveMailbox(mailboxAddress);
  limitMutations(user.id);
  const invalid = validateEventInput(input);
  if (invalid) return { ok: false, error: invalid };

  try {
    const client = await caldavClient(cred);
    const calendar = await assertOwnedCalendar(client, input.calendarId);
    const uid = newUID();
    const ics = buildEventICS(input, uid);
    const id = await putObject(client, calendar.url, `${uid}.ics`, ics);
    return { ok: true, id };
  } catch (e) {
    return { ok: false, error: cleanMsg(e) };
  }
}

/** Update an event in place, preserving its existing UID. */
export async function updateEvent(
  id: string,
  input: EventInput,
  mailboxAddress?: string,
): Promise<{ ok: boolean; error?: string }> {
  const { user, cred } = await resolveMailbox(mailboxAddress);
  limitMutations(user.id);
  if (!id?.trim()) return { ok: false, error: "Missing event id." };
  const invalid = validateEventInput(input);
  if (invalid) return { ok: false, error: invalid };

  try {
    const client = await caldavClient(cred);
    const existing = await readObject(client, id);
    const uid = (existing && uidFromICS(existing)) || newUID();
    const ics = buildEventICS(input, uid);
    await putObjectAt(client, id, ics);
    return { ok: true };
  } catch (e) {
    return { ok: false, error: cleanMsg(e) };
  }
}

/** Delete an event by its href. */
export async function deleteEvent(id: string, mailboxAddress?: string): Promise<void> {
  const { user, cred } = await resolveMailbox(mailboxAddress);
  limitMutations(user.id);
  if (!id?.trim()) throw new Error("Missing event id.");
  const client = await caldavClient(cred);
  await deleteObjectAt(client, id);
}

// ---------------------------------------------------------------------------
// Tasks (VTODO)
// ---------------------------------------------------------------------------

/** All tasks across the user's calendars. */
export async function listTasks(mailboxAddress?: string): Promise<TaskItem[]> {
  const { cred } = await resolveMailbox(mailboxAddress);
  const client = await caldavClient(cred);
  const cals = (await fetchCalendars(client)).filter((c) => supportsComponent(c, "VTODO"));

  const perCal = await Promise.all(
    cals.map(async (cal) => {
      const objs = await fetchTaskObjects(client, cal);
      return objs.flatMap((o) => (o.data ? parseTaskItems(o.data, cal.url, o.url) : []));
    }),
  );
  return perCal.flat();
}

/** Create a new task: PUT a fresh VTODO .ics object into the target calendar. */
export async function createTask(
  input: TaskInput,
  mailboxAddress?: string,
): Promise<{ ok: boolean; id?: string; error?: string }> {
  const { user, cred } = await resolveMailbox(mailboxAddress);
  limitMutations(user.id);
  const invalid = validateTaskInput(input);
  if (invalid) return { ok: false, error: invalid };

  try {
    const client = await caldavClient(cred);
    const calendar = await assertOwnedCalendar(client, input.calendarId);
    const uid = newUID();
    const ics = buildTaskICS(input, uid, false);
    const id = await putObject(client, calendar.url, `${uid}.ics`, ics);
    return { ok: true, id };
  } catch (e) {
    return { ok: false, error: cleanMsg(e) };
  }
}

/** Mark a task complete/incomplete, preserving its other fields. */
export async function setTaskCompleted(
  id: string,
  completed: boolean,
  mailboxAddress?: string,
): Promise<void> {
  const { user, cred } = await resolveMailbox(mailboxAddress);
  limitMutations(user.id);
  if (!id?.trim()) throw new Error("Missing task id.");

  const client = await caldavClient(cred);
  const existing = await readObject(client, id);
  if (!existing) throw new Error("That task was not found.");
  const updated = setTaskCompletedInICS(existing, completed);
  if (!updated) throw new Error("That task could not be updated.");
  await putObjectAt(client, id, updated);
}

/** Delete a task by its href. */
export async function deleteTask(id: string, mailboxAddress?: string): Promise<void> {
  const { user, cred } = await resolveMailbox(mailboxAddress);
  limitMutations(user.id);
  if (!id?.trim()) throw new Error("Missing task id.");
  const client = await caldavClient(cred);
  await deleteObjectAt(client, id);
}
